Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Section F8.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x5 x7 x8 x10 x11 x12 x16 x20 x22 x29 x30 : word).
  Variables (m : fmem) (DT SY cnt sym0 nb : Z) (syms : list (option Z)) (js jt : list byte) (ncells : nat).
  Variable POST : machine_state -> Prop.
  Notation SP := (bv_unsigned sp).
  Hypothesis HJT : length jt = (2 * ncells)%nat.
  Hypothesis HJS : length js = length syms.
  Hypothesis HSYR : forall i v, nth i syms None = Some v -> 0 <= v < 256.
  Hypothesis HNB : 0 <= nb < 16.
  Hypothesis HDT : 0 < DT /\ DT + 4 + 2 * Z.of_nat ncells <= 2^64.
  Hypothesis DJ : DT + 4 + 2 * Z.of_nat ncells <= SY \/ SY + zlen js <= DT + 4.
  Hypothesis HSP : DT + 4 + 2 * Z.of_nat ncells <= SP /\ SP + 64 <= 2^64.
  Hypothesis HSY : 0 < SY /\ SY + zlen js <= 2^64.
  Notation INV m1 cells := (x1f_inv m m1 DT SY js jt syms ncells cells).

  Lemma f8_inner : forall f s cells u (x14 x15 : word) m1 r (x1 x13 x17 x18 x25 x26 x27 x31 : word),
    fill_syms f s cnt sym0 8 nb syms cells u = Ok r ->
    Z.of_nat f = cnt - s + 1 -> 0 <= s < cnt -> 0 <= u -> 0 <= sym0 -> sym0 + cnt <= 512 -> INV m1 cells ->
    (forall m2 cells' (y1 y13 y17 y18 y23 y24 y25 y26 y27 y28 y31 : word),
       r = (cells', u + 8 * (cnt - s)) -> INV m2 cells' ->
       evt psegs POST (MS (mkR y1 sp gp tp x5 (Z_to_bv 64 nb) x7 x8 (Z_to_bv 64 DT) x10 x11 x12 y13 x14 x15 x16 y17 y18
                               (Z_to_bv 64 X1REP) x20 (Z_to_bv 64 cnt) x22 y23 y24 y25 y26 y27 y28 x29 x30 y31)
                          F (Z_to_bv 64 0x136e0) fc None m2 (seg_rom psegs))) ->
    evt psegs POST (MS (mkR x1 sp gp tp x5 (Z_to_bv 64 nb) x7 x8 (Z_to_bv 64 DT) x10 x11 x12 x13 x14 x15 x16 x17 x18
                            (Z_to_bv 64 X1REP) x20 (Z_to_bv 64 cnt) x22 (Z_to_bv 64 (DT + 12 + 2 * u))
                            (Z_to_bv 64 (DT + 12 + 2 * (u + 8 * (cnt - s)))) x25 x26 x27 (Z_to_bv 64 (SY + sym0 + s)) x29 x30 x31)
